import * as THREE from './vendor/three.module.js';
import {createLightHorse,LIGHT_ATLAS} from './horse-light-model.js';
import {GAME_CAMERA} from './hybrid-world.js';
import {unitArt} from './red-hats-art.js';
import {alphaBounds,rigidSpriteVertex} from './hybrid-sprites.js';
const $=id=>document.getElementById(id),host=$('scene'),renderer=new THREE.WebGLRenderer({antialias:true});renderer.setPixelRatio(Math.min(devicePixelRatio,2));renderer.setClearColor(0x383838);renderer.outputColorSpace=THREE.SRGBColorSpace;renderer.toneMapping=THREE.ACESFilmicToneMapping;host.append(renderer.domElement);
const scene=new THREE.Scene(),camera=new THREE.OrthographicCamera();scene.add(new THREE.HemisphereLight(0xfff9ec,0x737775,2));const light=new THREE.DirectionalLight(0xfff2dc,2.3);light.position.set(3,5,4);scene.add(light);const fill=new THREE.DirectionalLight(0xffffff,.7);fill.position.set(-2,2,-3);scene.add(fill);
const loader=new THREE.TextureLoader(),atlas=await loader.loadAsync(LIGHT_ATLAS);atlas.colorSpace=THREE.SRGBColorSpace;atlas.anisotropy=Math.min(4,renderer.capabilities.getMaxAnisotropy());
const data=await(await fetch('./horse-light-data.json')).json(),horse=createLightHorse(data,atlas);scene.add(horse.root);
const art=unitArt({species:'horse',outfit:'normal',weapon:'rifle',stance:'standing'}),texture=await loader.loadAsync(art.src);texture.colorSpace=THREE.SRGBColorSpace;texture.minFilter=texture.magFilter=THREE.NearestFilter;texture.generateMipmaps=false;
const source=document.createElement('canvas');source.width=art.width;source.height=art.height;const ctx=source.getContext('2d',{willReadFrequently:true});ctx.drawImage(texture.image,0,0);const bounds=alphaBounds(ctx.getImageData(0,0,art.width,art.height).data,art.width,art.height);
const sprite=new THREE.Mesh(new THREE.PlaneGeometry(1,1),new THREE.MeshBasicMaterial({map:texture,alphaTest:.4,toneMapped:false,side:THREE.DoubleSide}));scene.add(sprite);const p=sprite.geometry.attributes.position,uv=sprite.geometry.attributes.uv;for(let i=0;i<p.count;i++)p.setXYZ(i,...rigidSpriteVertex({heading:0},art,bounds,uv.getX(i)*art.width,(1-uv.getY(i))*art.height,GAME_CAMERA));sprite.geometry.computeBoundingSphere();
function render(){const close=$('close').checked,rifleOnly=$('pose').value==='rifle';host.style.height=close?'620px':'270px';host.style.width=close?'min(1000px,100%)':'min(660px,100%)';const w=host.clientWidth,h=host.clientHeight,ppu=close?300:58;renderer.setSize(w,h);renderer.setScissorTest(true);const heading=+$('heading').value;horse.pose($('pose').value==='neutral'?'neutral':'carry',heading);horse.setGrey($('grey').checked);horse.setGraphic($('graphic').checked);horse.material.wireframe=horse.grey.wireframe=$('wire').checked;
 for(let i=0;i<2;i++){const width=w/2;camera.left=-width/ppu/2;camera.right=width/ppu/2;camera.top=h/ppu/2;camera.bottom=-h/ppu/2;camera.near=.1;camera.far=30;const focus=new THREE.Vector3(0,.84,0),{azimuth:a,elevation:e}=GAME_CAMERA;camera.position.copy(focus).add(new THREE.Vector3(Math.sin(a)*Math.cos(e),Math.sin(e),Math.cos(a)*Math.cos(e)).multiplyScalar(5));camera.lookAt(focus);camera.updateProjectionMatrix();sprite.quaternion.copy(camera.quaternion);sprite.visible=i===0;horse.root.visible=i===1;for(const part of horse.parts)part.visible=!rifleOnly;renderer.setViewport(i*width,0,width,h);renderer.setScissor(i*width,0,width,h);renderer.render(scene,camera);}
 renderer.setScissorTest(false);horse.root.visible=true;sprite.visible=false;const d=horse.diagnostics();$('status').textContent=`${d.triangles.toLocaleString()} character triangles + ${d.rifleTriangles.toLocaleString()} rifle · ${d.bones} bones · ${d.skinnedMeshes} weighted surfaces · ${ppu} CSS px/unit. Max palm/contact error: ${Math.max(0,...d.contacts.map(c=>c.error)).toFixed(6)} world units. Reference: ${data.sourceTriangles.toLocaleString()} triangles.`;
}
for(const id of ['pose','close','grey','wire','heading','graphic'])$(id).addEventListener('input',render);new ResizeObserver(render).observe(host);render();window.lightHorse=horse;window.lightHorseDiagnostics=()=>({...horse.diagnostics(),pixelsPerUnit:host.clientHeight/(camera.top-camera.bottom),pose:$('pose').value,graphicPaint:$('graphic').checked});window.lightHorseReady=true;
